select
  id, study_id, patient_id, exam_no, test_no, create_time, update_time, result_time, hearing, auricle, external_auditory_meatus, tympanic_membrane, external_nose, nasal_cavity, oral_pharynx, laryngopharynx, tonsil
from td_otolaryngology


        and id = #{id}


        and study_id = #{studyId}


        and patient_id = #{patientId}


        and exam_no = #{examNo}


        and test_no = #{testNo}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and result_time = #{resultTime}


        and hearing = #{hearing}


        and auricle = #{auricle}


        and external_auditory_meatus = #{externalAuditoryMeatus}


        and tympanic_membrane = #{tympanicMembrane}


        and external_nose = #{externalNose}


        and nasal_cavity = #{nasalCavity}


        and oral_pharynx = #{oralPharynx}


        and laryngopharynx = #{laryngopharynx}


        and tonsil = #{tonsil}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from td_otolaryngology


        and id = #{id}


        and study_id = #{studyId}


        and patient_id = #{patientId}


        and exam_no = #{examNo}


        and test_no = #{testNo}


